        try {
            jdbcVirtualHostNode.setAttributes(Collections.singletonMap("tableNamePrefix", invalidPrefix));
            fail(String.format("Should not be able to set prefix to '%s'", invalidPrefix));
        } catch (IllegalConfigurationException e) {
            // pass
        }
    }
}

